const demoData={18:{year:2022,date:'2022.09.12',place:'北方校园 · 开学后的第二周',kind:'日记',text:'希望这次能勇敢一点，认识一些新朋友。',art:'campus',caption:'虚构示例 · 去教学楼的路',questions:['那一年的我，最在意什么？','我还记得当时为什么这么期待吗？','那时的我，会想对现在说什么？'],keywords:['勇敢','朋友','期待','在意'],answer:'那时的你，把“主动认识新朋友”看作一次需要勇气的小冒险。能确定的是，你期待新的关系，也在给自己打气。至于你后来有没有迈出那一步，这份记录没有说。'},22:{year:2026,date:'2026.06.18',place:'南方大学 · 毕业日',kind:'日记',text:'毕业的那一天，我发现有些告别并不是结束。',art:'station',caption:'虚构示例 · 被收进行李箱的学士帽',questions:['那一年的我，最舍不得什么？','离开学校时，我在想什么？','那时的我，会想对现在说什么？'],keywords:['告别','毕业','结束','舍不得','学校'],answer:'你没有把告别写成句号。记录里能确认的是：毕业让你重新理解了“结束”。至于最舍不得的人或事，这一页没有留下名字。'},26:{year:2030,date:'2030.04.07',place:'虚构未来 · 新城市',kind:'日记',text:'搬到新的城市后，我开始喜欢一个人慢慢散步。',art:'street',caption:'虚构示例 · 傍晚六点的街角',questions:['那时的生活是什么节奏？','为什么开始喜欢独自散步？','那时的我，会想对现在说什么？'],keywords:['城市','散步','一个人','节奏','喜欢'],answer:'这份虚构的未来记录写下了一个变化：来到新城市后，你开始享受独自散步。它像是把生活调慢了一格，但记录没有说明变化的具体原因。'}};
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const base=location.hostname.endsWith('github.io')?'/story-of-your-life':'';
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.id);toast.id=setTimeout(()=>t.classList.remove('show'),2400)}
function shell(){const b=$('.menu'),n=$('#nav');b?.addEventListener('click',()=>{const open=n.classList.toggle('open');b.setAttribute('aria-expanded',open)});const path=location.pathname;$$('nav a').forEach(a=>{if(a.pathname===path)a.setAttribute('aria-current','page')})}
function photo(d,cls=''){return `<figure class="photo ${cls}"><div class="photo-art ${d.art}" role="img" aria-label="${esc(d.caption)}，抽象演示插画"></div><figcaption>${esc(d.caption)}</figcaption></figure>`}
function home(){document.title='你一生的故事｜Story of Your Life';$('#main').innerHTML=`
  <section class="hero"><div class="hero-copy"><div class="eyebrow">STORY OF YOUR LIFE / AN UNFINISHED STORY</div><h1>一生很长，<br>你会遇见很多个自己。</h1><p>把散落在时间里的日记和照片重新摊开。不是复活谁，也不替过去编答案——只是循着真实记录，与你曾经的自己再聊一次。</p><div class="hero-actions"><a class="button red" href="${base}/demo/">见见过去的我</a><a class="button" href="${base}/studio/">开始我的故事</a></div></div><div class="collage" aria-label="三个时间切片组成的记忆拼贴">${photo(demoData[18],'one')}${photo(demoData[22],'two')}${photo(demoData[26],'three')}<span class="year-rail">2018 —— 2022 —— 2026 —— 现在</span><span class="scribble" style="position:absolute;right:5%;top:54%">那时，我在想什么？ ↗</span></div><span class="scroll-note">SCROLL TO TURN THE PAGE ↓</span></section>
  <section class="section river"><div class="river-line"></div><div class="river-intro"><div class="eyebrow">01 / TIME IS A RIVER</div><h2 class="section-title">时间不是档案柜，<br>它更像一条河。</h2><p>我们一直在变化。幸好，某天写下的一句话、随手拍的照片，还能替那个时刻留一把小小的锚。</p></div><div class="river-grid">${[{y:'2018',q:'第一次独自去很远的地方。',n:'TIME / 时间坐标'},{y:'2022',q:'“希望这次能勇敢一点。”',n:'MEMORY / 原始记录'},{y:'2026',q:'回看时，我不急着纠正当年的自己。',n:'ME / 今天的追问'}].map(x=>`<article class="river-item"><time>${x.y}</time><blockquote>${x.q}</blockquote><small>${x.n}</small></article>`).join('')}</div></section>
  <section class="section"><div class="eyebrow">02 / MEET YOURSELVES</div><h2 class="section-title">挑一个年纪，翻开那一页。</h2><div class="slices">${Object.entries(demoData).map(([age,d])=>`<article class="slice"><div class="age">${age}<sup>岁</sup></div><small>${d.date} · 虚构示例</small><blockquote>“${d.text}”</blockquote><a href="${base}/demo/?age=${age}">和这一年的我聊聊 →</a></article>`).join('')}</div></section>
  <section class="section"><div class="eyebrow">03 / HOW IT WORKS</div><h2 class="section-title">三步，把旧时光放回手边。</h2><div class="steps"><article class="step"><strong>1</strong><h3>放进一点旧时光</h3><p>一段带日期的日记，或几张你愿意留下的照片。</p></article><article class="step"><strong>2</strong><h3>重新整理那些片段</h3><p>按年月排进时间线；不确定的日期，诚实地留待补充。</p></article><article class="step"><strong>3</strong><h3>和过去的自己聊聊</h3><p>回答尽量引用原句。没有记载的事，我们就说不知道。</p></article></div></section>
  <section class="section story-spread"><h2 class="story-question">你还记得十七岁的自己，曾经为什么烦恼吗？</h2><aside class="story-margin"><span class="scribble">页边留白 / 允许记不清</span><p>记忆不是考试。这里不会替你补写标准答案。你可以回来看看，也可以合上这一页。</p></aside></section>
  <section class="section privacy"><div class="eyebrow">04 / A QUIET PROMISE</div><h2 class="section-title">你的故事，先属于你。</h2><div class="promises"><div class="promise"><b>默认私密</b><p>首版本地存储，不上传第三方。</p></div><div class="promise"><b>随时修改</b><p>日期、原文和卡片都由你决定。</p></div><div class="promise"><b>可以删除</b><p>单条移除，或一次清空本地资料。</p></div><div class="promise"><b>有据可查</b><p>结论附来源；不够就坦白说不够。</p></div></section>
  <section class="section final"><span class="scribble">THE FIRST PAGE CAN BE SMALL.</span><h2>从一张照片开始吧。</h2><a class="button red" href="${base}/studio/">翻开我的第一页</a></section>`;
  if(!matchMedia('(prefers-reduced-motion: reduce)').matches){addEventListener('scroll',()=>{$$('.collage .photo').forEach((p,i)=>p.style.translate=`0 ${Math.min(20,scrollY*(i+1)*.018)}px`)},{passive:true})}
}
function drawer(){return `<div class="drawer" hidden role="dialog" aria-modal="true" aria-labelledby="source-title"><div class="drawer-panel"><button class="close-drawer" aria-label="关闭来源详情">关闭</button><div class="eyebrow">ORIGINAL SOURCE / 原始资料</div><div class="source-paper"><h2 id="source-title"></h2><p class="source-meta"></p><blockquote class="source-text"></blockquote><p><small>这是公开 Demo 的虚构资料，不来自真实用户。</small></p></div></div></div>`}
function demo(){let age=Number(new URLSearchParams(location.search).get('age'))||18;if(!demoData[age])age=18;$('#main').innerHTML=`<header class="page-intro"><div><div class="eyebrow">A PUBLIC FICTIONAL DEMO</div><h1>和那一年的我，<br>坐一会儿。</h1></div><p class="notice">虚构示例 · 本地演示模式 · 并非真实 AI 推理<br>回答只使用本页展示的演示记录。</p></header><section class="demo-layout"><div><div class="age-selector" role="group" aria-label="选择年龄">${[18,22,26].map(a=>`<button data-age="${a}">${a} 岁</button>`).join('')}</div><div class="memory-stage"></div></div><div class="conversation"><div class="eyebrow">MARGINALIA / 书页旁白</div><h2>你想问那时的自己什么？</h2><div class="questions"></div><div class="answer" aria-live="polite"><p>选一个页边问题，或写下你的问题。这里不会假装知道记录之外的事。</p></div><form class="ask"><label class="sr-only" for="question">问题</label><input id="question" autocomplete="off" placeholder="例如：那一年，我最在意什么？"><button>写在页边</button></form></div></section>${drawer()}`;
  const render=()=>{const d=demoData[age];$$('.age-selector button').forEach(b=>b.classList.toggle('active',+b.dataset.age===age));$('.memory-stage').innerHTML=`${photo(d)}<article class="diary"><small>${d.date} · ${d.place}</small><p>“${d.text}”</p></article>`;$('.questions').innerHTML=d.questions.map(q=>`<button>${q}</button>`).join('');$('.answer').innerHTML='<p>这一页已经翻到你面前。想先问哪一句？</p>';$$('.questions button').forEach(b=>b.onclick=()=>ask(b.textContent))};
  const ask=q=>{const d=demoData[age],known=d.keywords.some(k=>q.includes(k))||q.includes('那时')||q.includes('那年');const reflection=q.includes('现在说什么');$('.answer').innerHTML=known?`<div class="eyebrow">${reflection?'今天的反思性创作，不是历史事实':'SUPPORTED BY ONE RECORD'}</div><p>${d.answer}</p>${reflection?'<p>如果把它写成今天的回信，也许是：“不用急着成为答案，先把当时的感受好好收下。”</p>':''}<button class="source" data-source>来源：${d.date} 日记 ↗</button>`:`<p>这段演示记录里没有足够信息。我们不替过去补写答案，你可以换个问题试试。</p>`;$('.answer [data-source]')?.addEventListener('click',openSource)};
  function openSource(){const d=demoData[age],dr=$('.drawer');$('#source-title').textContent=`${d.date} ${d.kind}`;$('.source-meta').textContent=d.place;$('.source-text').textContent=d.text;dr.hidden=false;$('.close-drawer').focus()}
  $$('.age-selector button').forEach(b=>b.onclick=()=>{age=+b.dataset.age;history.replaceState({},'',`?age=${age}`);render()});$('.ask').onsubmit=e=>{e.preventDefault();const i=$('#question');if(i.value.trim())ask(i.value.trim())};$('.close-drawer').onclick=()=>$('.drawer').hidden=true;$('.drawer').onclick=e=>{if(e.target.classList.contains('drawer'))e.currentTarget.hidden=true};render()
}
const DB='story-life-local',STORE='memories';let db;
function openDB(){return new Promise((res,rej)=>{const req=indexedDB.open(DB,1);req.onupgradeneeded=()=>req.result.createObjectStore(STORE,{keyPath:'id'});req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)})}
function tx(mode='readonly'){return db.transaction(STORE,mode).objectStore(STORE)}
function all(){return new Promise((res,rej)=>{const r=tx().getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function put(x){return new Promise((res,rej)=>{const r=tx('readwrite').put(x);r.onsuccess=res;r.onerror=()=>rej(r.error)})}
function del(id){return new Promise((res,rej)=>{const r=tx('readwrite').delete(id);r.onsuccess=res;r.onerror=()=>rej(r.error)})}
function studio(){document.title='私人工作台｜你一生的故事';$('#main').innerHTML=`<header class="page-intro"><div><div class="eyebrow">PRIVATE WORKSPACE / LOCAL FIRST</div><h1>你的记忆档案</h1></div><p class="notice">本地演示模式 · 资料仅保存在此浏览器的 IndexedDB 中，不等于加密云存储。</p></header><div class="studio-tabs" role="tablist"><button class="active" data-tab="add">放入记忆</button><button data-tab="timeline">时间线</button><button data-tab="talk">过去的我</button><button data-tab="cards">记忆卡片</button><button data-tab="settings">数据与隐私</button></div><div class="studio"><section class="panel active" id="add"><div class="two-col"><form class="form-paper" id="diary-form"><div class="eyebrow">TEXT DIARY</div><h2>写下一段旧日记</h2><input type="hidden" name="id"><label for="diary-title">标题（可选）</label><input id="diary-title" name="title" maxlength="80"><label for="diary-date">日期（必填）</label><input id="diary-date" type="date" name="date" required><label for="diary-text">正文（必填）</label><textarea id="diary-text" name="text" required></textarea><div class="form-actions"><button>保存日记</button><button type="button" class="ghost cancel-edit" hidden>取消编辑</button></div></form><div><div class="dropzone" tabindex="0"><div class="eyebrow">PHOTO MEMORY</div><h2>把照片放到这里</h2><p>支持多选；照片不会离开此浏览器。请自行确认拍摄日期。</p><label class="button">选择照片<input type="file" accept="image/*" multiple hidden></label></div><form class="form-paper photo-form" hidden><div class="eyebrow">CONFIRM THE DATE</div><h3 class="photo-name"></h3><img class="photo-preview" alt="待保存照片预览" style="width:100%;max-height:220px;object-fit:cover"><label for="photo-date">拍摄日期（无法自动确认时请填写）</label><input id="photo-date" type="date" name="date"><label for="photo-note">照片备注</label><textarea id="photo-note" name="text"></textarea><div class="form-actions"><button>保存这张照片</button><button type="button" class="skip-photo ghost">跳过</button></div></form></div></div></section><section class="panel" id="timeline"><div class="timeline-list"></div></section><section class="panel" id="talk"><div class="two-col"><div><label for="year-select">选择一个年份</label><select id="year-select"></select><div class="answer local-answer"><p>选择有资料的年份，再写下你的问题。</p></div></div><form class="form-paper local-ask"><h2>写给那一年的我</h2><label for="local-question">问题</label><textarea id="local-question" required placeholder="那一年，我最在意什么？"></textarea><button class="button">从记录里找一找</button></form></div></section><section class="panel" id="cards"><div class="cards-list"></div></section><section class="panel" id="settings"><div class="settings"><div><h2>带走你的资料</h2><p>导出为 JSON。照片以 Data URL 保存在文件中，文件可能较大。</p><button class="button export">导出 JSON</button></div><div><h2>清空本地数据</h2><p>这会删除本浏览器里的日记、照片和记忆卡片，无法撤销。</p><button class="button danger clear">清空全部资料</button></div><div><h2>尚未开放</h2><p>语音、视频、微信 Bot 与真实 AI 接口不在本地首版中。</p></div></div></section></div>${drawer()}`;initStudio().catch(()=>toast('浏览器本地存储不可用'))}
async function initStudio(){db=await openDB();let photoQueue=[],editing=null;const refresh=async()=>{const items=(await all()).sort((a,b)=>(b.date||'').localeCompare(a.date||''));renderTimeline(items);renderYears(items);renderCards(items)};
  $$('.studio-tabs button').forEach(b=>b.onclick=()=>{$$('.studio-tabs button,.panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#'+b.dataset.tab).classList.add('active');refresh()});
  $('#diary-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,f=new FormData(form),id=f.get('id')||crypto.randomUUID();await put({id,type:'diary',title:f.get('title'),date:f.get('date'),text:f.get('text'),createdAt:new Date().toISOString()});form.reset();$('.cancel-edit').hidden=true;toast('日记已留在这一页');refresh()};$('.cancel-edit').onclick=()=>{$('#diary-form').reset();$('.cancel-edit').hidden=true};
  const input=$('.dropzone input'),drop=$('.dropzone');input.onchange=()=>queueFiles([...input.files]);drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');queueFiles([...e.dataTransfer.files].filter(f=>f.type.startsWith('image/')))};drop.onkeydown=e=>{if(e.key==='Enter')input.click()};
  function queueFiles(files){photoQueue.push(...files);nextPhoto()};function nextPhoto(){if(editing||!photoQueue.length)return;editing=photoQueue.shift();const r=new FileReader();r.onload=()=>{editing.url=r.result;$('.photo-preview').src=r.result;$('.photo-name').textContent=editing.name;$('.photo-form').hidden=false};r.readAsDataURL(editing)}
  $('.photo-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,f=new FormData(form);await put({id:crypto.randomUUID(),type:'photo',title:editing.name,date:f.get('date')||'',text:f.get('text'),image:editing.url,createdAt:new Date().toISOString()});form.reset();form.hidden=true;editing=null;toast('照片已保存；日期由你确认');refresh();nextPhoto()};$('.skip-photo').onclick=()=>{$('.photo-form').reset();$('.photo-form').hidden=true;editing=null;nextPhoto()};
  function renderTimeline(items){const el=$('.timeline-list');if(!items.length){el.innerHTML='<div class="empty">这一页暂时空着，我们慢慢写。</div>';return}const groups=Object.groupBy?Object.groupBy(items,x=>x.date?x.date.slice(0,7):'待补时间'):items.reduce((a,x)=>((a[x.date?x.date.slice(0,7):'待补时间']??=[]).push(x),a),{});el.innerHTML=Object.entries(groups).map(([m,xs])=>`<section class="timeline"><h2>${m}</h2>${xs.map(x=>`<article class="memory-row" data-id="${x.id}"><small>${x.type==='diary'?'日记':'照片'} · ${x.date||'日期待补'}</small><h3>${esc(x.title||x.text?.slice(0,24)||'一张照片')}</h3><p>${esc(x.text||'没有备注')}</p>${x.image?`<img src="${x.image}" alt="${esc(x.text||x.title||'用户上传的记忆照片')}">`:''}<div class="row-actions">${x.type==='diary'?'<button data-edit>编辑</button>':''}<button data-source>查看原始资料</button><button class="danger" data-delete>删除</button></div></article>`).join('')}</section>`).join('');$$('[data-delete]',el).forEach(b=>b.onclick=async()=>{const row=b.closest('[data-id]');if(confirm('确定删除这条记忆吗？')){await del(row.dataset.id);toast('这条记忆已删除');refresh()}});$$('[data-edit]',el).forEach(b=>b.onclick=()=>{const x=items.find(i=>i.id===b.closest('[data-id]').dataset.id),f=$('#diary-form');f.elements.id.value=x.id;f.elements.title.value=x.title||'';f.elements.date.value=x.date;f.elements.text.value=x.text;$('.cancel-edit').hidden=false;$$('.studio-tabs button')[0].click();f.elements.text.focus()});$$('[data-source]',el).forEach(b=>b.onclick=()=>openLocal(items.find(i=>i.id===b.closest('[data-id]').dataset.id)))}
  function openLocal(x){const dr=$('.drawer');$('#source-title').textContent=x.title||x.date||'未命名记忆';$('.source-meta').textContent=`${x.type==='diary'?'文字日记':'照片'} · ${x.date||'日期待补'}`;$('.source-text').textContent=x.text||'没有文字备注';dr.hidden=false}
  $('.close-drawer').onclick=()=>$('.drawer').hidden=true;
  function renderYears(items){const years=[...new Set(items.filter(x=>x.date).map(x=>x.date.slice(0,4)))];$('#year-select').innerHTML=years.length?years.map(y=>`<option>${y}</option>`).join(''):'<option value="">还没有带日期的资料</option>'}
  $('.local-ask').onsubmit=async e=>{e.preventDefault();const year=$('#year-select').value,q=$('textarea',e.currentTarget).value.trim(),items=(await all()).filter(x=>x.date?.startsWith(year));if(!items.length){$('.local-answer').innerHTML='<p>这一年还没有足够资料。先放进一则日记或照片吧。</p>';return}const words=q.match(/[\u4e00-\u9fa5]{2,}|[a-z]{3,}/gi)||[],match=items.find(x=>words.some(w=>(x.text||'').includes(w)))||items[0];$('.local-answer').innerHTML=`<div class="eyebrow">本地关键词检索 · 并非 AI 推理</div><p>这份记录里写着：“${esc(match.text||match.title||'一张没有备注的照片')}”</p><p>它不足以代表那一整年的你，但可以作为继续回想的起点。</p><button class="source">来源：${esc(match.date||'日期待补')} ${match.type==='diary'?'日记':'照片'} ↗</button>`;$('.local-answer .source').onclick=()=>openLocal(match)};
  function renderCards(items){const saved=items.filter(x=>x.type==='card'),sources=items.filter(x=>x.type!=='card'&&x.date);$('.cards-list').innerHTML=`<div class="summary-card"><div class="eyebrow">A SMALL RESULT</div><h3 contenteditable="true">那一年的我</h3><p contenteditable="true">${sources.length?`我留下了 ${sources.length} 条有日期的记录。最新的一页写着：“${esc(sources[0].text||sources[0].title||'一张照片')}”`:'先放进一段有日期的记忆，这张卡才有话可写。'}</p><button class="button save-card" ${sources.length?'':'disabled'}>保存到本地</button></div>${saved.map(x=>`<article class="memory-row" data-id="${x.id}"><small>已保存卡片 · ${x.date}</small><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p><button class="danger" data-delete-card>删除卡片</button></article>`).join('')}`;$('.save-card')?.addEventListener('click',async()=>{const c=$('.summary-card');await put({id:crypto.randomUUID(),type:'card',title:$('h3',c).textContent.trim(),text:$('p',c).textContent.trim(),date:new Date().toISOString().slice(0,10)});toast('记忆卡片已保存');refresh()});$$('[data-delete-card]').forEach(b=>b.onclick=async()=>{if(confirm('删除这张记忆卡片吗？')){await del(b.closest('[data-id]').dataset.id);refresh()}})}
  $('.export').onclick=async()=>{const data=JSON.stringify(await all(),null,2),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type:'application/json'}));a.download=`story-of-your-life-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);toast('资料已导出')};$('.clear').onclick=async()=>{if(!confirm('确定清空全部本地资料吗？此操作无法撤销。'))return;await new Promise((res,rej)=>{const r=tx('readwrite').clear();r.onsuccess=res;r.onerror=()=>rej(r.error)});toast('本地资料已清空');refresh()};await refresh()}
